import { 
  Button, 
  Card, 
  CardBody, 
  Heading, 
  Text, 
  Flex, 
  HStack, 
  CardHeader, 
  CardFooter,
  Input,
  Textarea,
  useDisclosure,
  useColorModeValue,
  Menu,
  MenuButton,
  MenuList,
  MenuDivider,
  Tooltip,
  Wrap,
  WrapItem,
  Tag,
} from "@chakra-ui/react";
import { useRef, useState } from "react";
import { useDispatch } from "react-redux";
import { store } from "../../../redux/store";
import { BASE_URL } from "../../../constants/config";
import { deleteNotes, updateNotes } from "../../../redux/notes/note_actions";
import {
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
} from "@chakra-ui/react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  EditIcon, 
  DeleteIcon, 
  HamburgerIcon, 
  ExternalLinkIcon,
  CopyIcon,
  StarIcon,
} from "@chakra-ui/icons";

const gradients = [
  "linear-gradient(145deg, #19231f, #151d1a)",
  "linear-gradient(145deg, #20231d, #191d18)",
  "linear-gradient(145deg, #1a2224, #151d1e)",
  "linear-gradient(145deg, #211f1b, #191815)",
];

const cardVariants = {
  hidden: { opacity: 0, y: 12 },
  visible: (i) => ({
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.35,
      delay: i * 0.04,
      ease: "easeOut",
    },
  }),
  hover: { y: -4, transition: { duration: 0.18, ease: "easeOut" } },
  tap: { scale: 0.99 },
  exit: { opacity: 0, y: -8, transition: { duration: 0.18 } },
};

const contentVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.4, delay: 0.2 } },
};

export default function NoteCard({ title, body, user, _id, createdAt, updatedAt, summary, tags = [], index = 0 }) {
  const dispatch = useDispatch();
  const { isOpen, onOpen, onClose } = useDisclosure();
  const initialRef = useRef(null);
  const finalRef = useRef(null);
  const [tempTitle, setTitle] = useState(title);
  const [tempBody, setBody] = useState(body);
  const [isEditing, setIsEditing] = useState(false);
  const [aiBusy, setAiBusy] = useState(false);
  const [isFavorite, setIsFavorite] = useState(false);
  const cardRef = useRef(null);

  const gradient = gradients[_id ? parseInt(_id.slice(-1), 16) % gradients.length : index % gradients.length];
  const borderColor = useColorModeValue("rgba(0, 0, 0, 0.05)", "rgba(255, 255, 255, 0.05)");

  const runAiAction = async (action) => {
    if (!tempBody.trim() || aiBusy) return;
    setAiBusy(true);
    try {
      const token = store.getState().userReducer.token;
      const response = await fetch(`${BASE_URL}/api/ai/transform`, { method: "POST", headers: { "Content-Type": "application/json", Authorization: token }, body: JSON.stringify({ action, title: tempTitle, text: tempBody }) });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || "AI action failed");
      setBody(result.result || tempBody);
    } catch (error) { window.alert(error.message || "AI action failed"); }
    finally { setAiBusy(false); }
  };

  const updateNote = () => {
    dispatch(updateNotes(_id, { title: tempTitle, body: tempBody }));
    onClose();
    setIsEditing(false);
  };

  const handleDelete = () => {
    if (window.confirm("Are you sure you want to delete this note?")) {
      dispatch(deleteNotes(_id));
    }
  };

  const handleCopy = async () => {
    await navigator.clipboard.writeText(`${title}

${body}`);
  };

  const formatDate = (dateString) => {
    if (!dateString) return "";
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", { 
      month: "short", 
      day: "numeric", 
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  return (
    <motion.article
      ref={cardRef}
      variants={cardVariants}
      custom={index}
      initial="hidden"
      animate="visible"
      whileHover="hover"
      whileTap="tap"
      exit="exit"
      layout
      style={{
        perspective: '1000px',
        transformStyle: 'preserve-3d',
      }}
    >
      <Card
        className="card-3d"
        align="center"
        size="md"
        style={{
          background: gradient,
          border: `1px solid ${borderColor}`,
          borderRadius: '20px',
          overflow: 'hidden',
          position: 'relative',
          transformStyle: 'preserve-3d',
          minHeight: '280px',
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        {/* HEADER */}
        <CardHeader
          height="auto"
          alignItems="flex-start"
          justifyContent="space-between"
          style={{
            padding: '20px 20px 12px',
            position: 'relative',
            zIndex: 2,
          }}
        >
          <motion.div
            variants={contentVariants}
            style={{ flex: 1 }}
          >
            <Heading 
              size="lg" 
              noOfLines={1} 
              style={{ 
                color: 'white', 
                fontWeight: 800, 
                textShadow: '0 2px 10px rgba(0,0,0,0.3)',
                marginBottom: '4px',
              }}
            >
              {title}
            </Heading>
            <Text 
              noOfLines={1} 
              fontSize="sm" 
              style={{ color: 'rgba(255,255,255,0.7)' }}
            >
              {createdAt && `Created ${formatDate(createdAt)}`}{' '}
              {updatedAt && createdAt && '·'}{' '}
              {updatedAt && `Updated ${formatDate(updatedAt)}`}
            </Text>
          </motion.div>

          {/* ACTIONS MENU */}
          <motion.div
            variants={contentVariants}
            style={{ display: 'flex', alignItems: 'center', gap: '8px' }}
          >
            <Tooltip label="Favorite">
              <motion.button
                whileHover="hover"
                whileTap="tap"
                onClick={() => setIsFavorite(!isFavorite)}
                style={{
                  padding: '8px',
                  borderRadius: '10px',
                  background: 'rgba(255, 255, 255, 0.15)',
                  border: 'none',
                  cursor: 'pointer',
                  color: isFavorite ? '#ff6b6b' : 'rgba(255,255,255,0.8)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  backdropFilter: 'blur(10px)',
                }}
              >
                <StarIcon size={18} />
              </motion.button>
            </Tooltip>

            <Tooltip label="Copy">
              <motion.button
                whileHover="hover"
                whileTap="tap"
                onClick={handleCopy}
                style={{
                  padding: '8px',
                  borderRadius: '10px',
                  background: 'rgba(255, 255, 255, 0.15)',
                  border: 'none',
                  cursor: 'pointer',
                  color: 'rgba(255,255,255,0.8)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  backdropFilter: 'blur(10px)',
                }}
              >
                <CopyIcon size={18} />
              </motion.button>
            </Tooltip>

            <Menu>
              <MenuButton
                as={motion.button}
                whileHover="hover"
                whileTap="tap"
                style={{
                  padding: '8px',
                  borderRadius: '10px',
                  background: 'rgba(255, 255, 255, 0.15)',
                  border: 'none',
                  cursor: 'pointer',
                  color: 'rgba(255,255,255,0.8)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  backdropFilter: 'blur(10px)',
                }}
              >
                <HamburgerIcon size={18} />
              </MenuButton>

              <MenuList
                style={{
                  borderRadius: '12px',
                  background: 'rgba(20, 20, 30, 0.95)',
                  backdropFilter: 'blur(20px)',
                  border: '1px solid rgba(255, 255, 255, 0.1)',
                  boxShadow: '0 20px 50px rgba(0, 0, 0, 0.4)',
                  overflow: 'hidden',
                  minWidth: '160px',
                }}
              >
                <motion.button
                  type="button"
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.05 }}
                  onClick={() => { onOpen(); setIsEditing(true); }}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '10px',
                    padding: '12px 16px',
                    color: 'white',
                    cursor: 'pointer',
                    background: 'transparent',
                    border: 'none',
                    width: '100%',
                    fontSize: '0.9rem',
                  }}
                >
                  <EditIcon size={18} color="#5b9cf2" />
                  Edit Note
                </motion.button>

                <MenuDivider style={{ borderColor: 'rgba(255, 255, 255, 0.1)', mx: 3 }} />

                <motion.button
                  type="button"
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.1 }}
                  onClick={handleDelete}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '10px',
                    padding: '12px 16px',
                    color: '#ff6b6b',
                    cursor: 'pointer',
                    background: 'transparent',
                    border: 'none',
                    width: '100%',
                    fontSize: '0.9rem',
                  }}
                >
                  <DeleteIcon size={18} color="#ff6b6b" />
                  Delete
                </motion.button>
              </MenuList>
            </Menu>
          </motion.div>
        </CardHeader>

        {/* BODY */}
        <CardBody 
          mt={0}
          style={{ 
            flex: 1, 
            padding: '0 20px 16px', 
            position: 'relative', 
            zIndex: 2,
            display: 'flex',
            flexDirection: 'column',
          }}
        >
          <motion.div
            variants={contentVariants}
            style={{ flex: 1, overflow: 'hidden' }}
          >
            <Text 
              noOfLines={6} 
              style={{ 
                color: 'rgba(255,255,255,0.9)', 
                lineHeight: 1.7, 
                fontSize: '0.95rem',
                fontWeight: 400,
              }}
            >
              {body}
            </Text>
            {summary && <Text mt={2} noOfLines={2} fontSize="xs" color="whiteAlpha.700">{summary}</Text>}
            {!!tags.length && <Wrap mt={2} spacing={1}>{tags.map((tag) => <WrapItem key={tag}><Tag size="sm" variant="subtle" colorScheme="green">{tag}</Tag></WrapItem>)}</Wrap>}
          </motion.div>
        </CardBody>

        {/* FOOTER */}
        <CardFooter 
          height="auto" 
          style={{ 
            padding: '12px 20px 20px', 
            position: 'relative', 
            zIndex: 2,
            borderTop: `1px solid ${borderColor}`,
            marginTop: 'auto',
          }}
        >
          <HStack width="100%" justifyContent="space-between" alignItems="center">
            <motion.div
              variants={contentVariants}
              style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}
            >
              <span style={{ 
                fontSize: '0.75rem', 
                fontWeight: 600, 
                color: 'rgba(255,255,255,0.6)',
                textTransform: 'uppercase',
                letterSpacing: '1px',
              }}>
                {user || 'Unknown'}
              </span>
              <span
                style={{
                  width: '8px',
                  height: '8px',
                  borderRadius: '50%',
                  background: '#b7cfaa',
                }}
              />
              <span style={{ 
                fontSize: '0.7rem', 
                color: 'rgba(255,255,255,0.5)',
              }}>
                Saved
              </span>
            </motion.div>

            <motion.div
              variants={contentVariants}
              style={{ display: 'flex', alignItems: 'center', gap: '8px' }}
            >
              <Tooltip label="Open Note">
                <motion.button
                  whileHover="hover"
                  whileTap="tap"
                  onClick={() => { onOpen(); setIsEditing(true); }}
                  style={{
                    padding: '10px',
                    borderRadius: '10px',
                    background: 'rgba(255, 255, 255, 0.15)',
                    border: 'none',
                    cursor: 'pointer',
                    color: 'rgba(255,255,255,0.9)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    backdropFilter: 'blur(10px)',
                  }}
                >
                  <ExternalLinkIcon size={18} />
                </motion.button>
              </Tooltip>
            </motion.div>
          </HStack>
        </CardFooter>

        {/* EDIT MODAL */}
        <AnimatePresence>
          {isOpen && (
            <Modal
              initialFocusRef={initialRef}
              finalFocusRef={finalRef}
              isOpen={isOpen}
              onClose={() => { onClose(); setIsEditing(false); }}
              style={{ zIndex: 10000 }}
            >
              <ModalOverlay
                bg="rgba(0, 0, 0, 0.7)"
                style={{ backdropFilter: 'blur(5px)' }}
              />
              <ModalContent
                style={{
                  maxWidth: '600px',
                  borderRadius: '24px',
                  background: 'rgba(20, 20, 30, 0.95)',
                  backdropFilter: 'blur(20px)',
                  border: '1px solid rgba(255, 255, 255, 0.1)',
                  boxShadow: '0 30px 80px rgba(0, 0, 0, 0.5)',
                }}
              >
                <ModalHeader style={{ color: 'white', borderBottom: '1px solid rgba(255,255,255,0.1)', px: 6, py: 4 }}>
                  <Flex justifyContent="space-between" alignItems="center" width="100%">
                    <Heading size="lg" style={{ fontWeight: 700 }}>
                      {isEditing ? "Edit Note" : "View Note"}
                    </Heading>
                    <ModalCloseButton color="white" />
                  </Flex>
                </ModalHeader>
                <ModalCloseButton />
                <ModalBody pb={6} style={{ px: 6, pt: 4 }}>
                  <Input
                    value={tempTitle}
                    placeholder="Note title..."
                    onChange={(e) => setTitle(e.target.value)}
                    style={{
                      background: 'rgba(255, 255, 255, 0.05)',
                      border: '1px solid rgba(255, 255, 255, 0.1)',
                      borderRadius: '12px',
                      color: 'white',
                      '&::placeholder': { color: 'rgba(255,255,255,0.4)' },
                      '&:focus': { borderColor: '#5b9cf2', boxShadow: '0 0 0 3px rgba(91, 156, 242, 0.2)' },
                    }}
                  ></Input>

                  <Textarea
                    mt={4}
                    value={tempBody}
                    placeholder="Write your thoughts here..."
                    onChange={(e) => setBody(e.target.value)}
                    minHeight="200px"
                    style={{
                      background: 'rgba(255, 255, 255, 0.05)',
                      border: '1px solid rgba(255, 255, 255, 0.1)',
                      borderRadius: '12px',
                      color: 'white',
                      '&::placeholder': { color: 'rgba(255,255,255,0.4)' },
                      '&:focus': { borderColor: '#5b9cf2', boxShadow: '0 0 0 3px rgba(91, 156, 242, 0.2)' },
                      resize: 'vertical',
                    }}
                  ></Textarea>
                  <Text mt={4} mb={2} color="whiteAlpha.700" fontSize="sm" fontWeight="600">AI writing tools</Text>
                  <Wrap spacing={2}>
                    {[ ["summarize", "Summarize"], ["expand", "Expand"], ["reformat", "Reformat"], ["grammar", "Fix grammar"], ["rewrite", "Rewrite"], ["translate", "Translate"], ["actions", "Action items"] ].map(([action, label]) => <WrapItem key={action}><Button size="xs" variant="outline" color="white" isLoading={aiBusy} isDisabled={aiBusy || !tempBody.trim()} onClick={() => runAiAction(action)}>{label}</Button></WrapItem>)}
                  </Wrap>
                </ModalBody>

                <ModalFooter style={{ px: 6, pb: 4, borderTop: '1px solid rgba(255,255,255,0.1)' }}>
                  <Button 
                    colorScheme="blue" 
                    mr={3} 
                    onClick={updateNote}
                    style={{
                      borderRadius: '12px',
                      fontWeight: 600,
                      padding: '12px 28px',
                    }}
                  >
                    {isEditing ? "Save Changes" : "Close"}
                  </Button>
                  <Button 
                    onClick={() => { onClose(); setIsEditing(false); }}
                    variant="ghost"
                    color="white"
                    style={{
                      borderRadius: '12px',
                      fontWeight: 600,
                      padding: '12px 28px',
                    }}
                  >
                    Cancel
                  </Button>
                </ModalFooter>
              </ModalContent>
            </Modal>
          )}
        </AnimatePresence>
      </Card>
    </motion.article>
  );
}
